'use client'

import './photo-pile.css'
import { type PhotoPileOptions, photoPile } from '@kida-ui/motion'
import type { CSSProperties, HTMLAttributes, ImgHTMLAttributes } from 'react'
import { forwardRef, useRef } from 'react'
import { composeRefs } from './compose-refs.js'
import { useIsomorphicLayoutEffect } from './use-isomorphic-layout-effect.js'

export interface PhotoPilePhoto {
  /** Stable key for this photo. */
  id: string
  src: string
  alt: string
  /** Horizontal offset from the center, in CSS pixels. */
  x?: number
  /** Vertical offset from the center, in CSS pixels. */
  y?: number
  /** Resting rotation in degrees. */
  rotation?: number
  imageProps?: Omit<ImgHTMLAttributes<HTMLImageElement>, 'src' | 'alt' | 'draggable'>
}

export interface PhotoPileProps
  extends PhotoPileOptions,
    Omit<HTMLAttributes<HTMLFieldSetElement>, 'children'> {
  photos: readonly PhotoPilePhoto[]
  /** Multiplies the default and authored x/y offsets. @default 1 */
  spread?: number
}

const POSITIONS = [
  { x: -54, y: -10, rotation: -7 },
  { x: 52, y: -18, rotation: 6 },
  { x: 2, y: 30, rotation: -1.5 },
  { x: -24, y: -38, rotation: 4 },
  { x: 38, y: 24, rotation: -5 },
] as const

type ItemStyle = CSSProperties & {
  '--kida-photo-x': string
  '--kida-photo-y': string
  '--kida-photo-rotation': string
}

export const PhotoPile = forwardRef<HTMLFieldSetElement, PhotoPileProps>(function PhotoPile(
  { photos, spread = 1, dragScale, tilt, 'aria-label': ariaLabel, ...props },
  forwardedRef,
) {
  const ref = useRef<HTMLFieldSetElement>(null)
  const photoKey = photos.map((photo) => photo.id).join('\u0000')

  useIsomorphicLayoutEffect(() => {
    const root = ref.current
    if (!root) return
    return photoPile(root, { dragScale, tilt })
  }, [photoKey, dragScale, tilt])

  return (
    <fieldset
      {...props}
      ref={composeRefs(ref, forwardedRef)}
      aria-label={ariaLabel ?? 'Draggable photo pile'}
      data-kida-photo-pile=""
    >
      {photos.map((photo, index) => {
        const fallback = POSITIONS[index % POSITIONS.length] ?? POSITIONS[0]
        const label = photo.alt || `Photo ${index + 1}`
        const style: ItemStyle = {
          '--kida-photo-x': `${(photo.x ?? fallback.x) * spread}px`,
          '--kida-photo-y': `${(photo.y ?? fallback.y) * spread}px`,
          '--kida-photo-rotation': `${photo.rotation ?? fallback.rotation}deg`,
          zIndex: index + 1,
        }

        return (
          <button
            key={photo.id}
            type="button"
            aria-label={`Bring ${label} to front and drag`}
            data-kida-photo-item=""
            style={style}
          >
            <span data-kida-photo-card="">
              <img {...photo.imageProps} src={photo.src} alt={photo.alt} draggable={false} />
            </span>
          </button>
        )
      })}
    </fieldset>
  )
})

import type { Ref } from 'react'

/** Feed one node to several refs — ours for measuring, Zag's for animation detection. */
export function composeRefs<T>(...refs: (Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === 'function') ref(node)
      else if (ref) (ref as { current: T | null }).current = node
    }
  }
}

[data-kida-photo-pile] {
  --kida-photo-width: clamp(9rem, 42%, 13.5rem);
  --kida-photo-radius: 0.55rem;
  --kida-photo-frame: #fffafb;
  --kida-photo-shadow: 0 0.8rem 2rem rgb(50 30 42 / 16%);

  position: relative;
  display: block;
  min-inline-size: 0;
  width: min(100%, 36rem);
  min-height: 22rem;
  margin: 0;
  padding: 0;
  border: 0;
  isolation: isolate;
}

[data-kida-photo-item] {
  position: absolute;
  top: 50%;
  left: 50%;
  width: var(--kida-photo-width);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--kida-photo-radius);
  background: transparent;
  cursor: grab;
  touch-action: none;
  transform: translate(-50%, -50%) translate(var(--kida-photo-x), var(--kida-photo-y))
    rotate(var(--kida-photo-rotation));
}

[data-kida-photo-item][data-dragging] {
  cursor: grabbing;
}

[data-kida-photo-item]:focus-visible {
  outline: 3px solid var(--kida-photo-focus, #6d52a8);
  outline-offset: 5px;
}

[data-kida-photo-card] {
  display: block;
  padding: 0.45rem 0.45rem 1.8rem;
  border: 1px solid rgb(55 35 48 / 12%);
  border-radius: var(--kida-photo-radius);
  background: var(--kida-photo-frame);
  box-shadow: var(--kida-photo-shadow);
  user-select: none;
}

[data-kida-photo-card] img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 5;
  border-radius: calc(var(--kida-photo-radius) - 0.2rem);
  object-fit: cover;
  pointer-events: none;
}

@media (max-width: 32rem) {
  [data-kida-photo-pile] {
    --kida-photo-width: min(48%, 10.5rem);

    min-height: 18rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-kida-photo-card] {
    /* biome-ignore lint/complexity/noImportantStyles: stops an in-flight inline transform */
    transform: none !important;
  }
}
